//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vIsurCd;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDSTF92021.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 * 주식발행내역 목록 조회
 */
scwin.fn_list_sync = function() {
    var url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_DSCL_KOSDAQ + "&ISUR_CD=" + scwin.vIsurCd;
    dts_IssRecv.DataID = encodeURI(url);
    dts_IssRecv.reset();
};
scwin.fn_OpenDetail = function(row) {
    var url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_DTL_DSCL_KOSDAQ + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "LIST_DD") + "&GUBUN_CD=" + dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "STK_ISU_RSN_CD") + "&LIST_METHD_TP_CD=" + dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "LIST_METHD_TP_CD");
    dts_IssList.DataID = encodeURI(url);
    dts_IssList.reset();

    /* 2009.06.08 영문공시관련 추가 */
    url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_DTL_DSCL_KOSDAQ_ENG + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "LIST_DD") + "&GUBUN_CD=" + dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "STK_ISU_RSN_CD") + "&LIST_METHD_TP_CD=" + dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "LIST_METHD_TP_CD");
    dts_IssList_Eng.DataID = encodeURI(url);
    dts_IssList_Eng.reset();
    /* 2009.06.08 영문공시관련 추가 End */

};
scwin.fn_getRsnCse = function(strRsn) {
    var arr = [ // 상장업무구분코드,  
        ["130", ["602", "603", "604", "605", "606", "607", "608", "611", "612", "613", "614", "615", "616", "617", "618", "619", "620", "621", "622", "623", "624", "625", "628", "629", "630", "631", "642", "644", "646", "647"]],
        // 추가상장(기타도 포함)
        ["141", ["609", "610", "626", "627", "632", "633", "648", "649", "699", "650", "625"]], // 변경상장 (632 무액면, 633 액면, 648 주식병합(무액면주식), 649 주식분할(무액면주식) 650주식소각625우선주의 보통주전환)
        ["148", ["643"]], // 상호변경
        ["141A", ["640", "641"]], // 액면변경
        ["100B", ["601"]]
    ];
    for (var i = 0; i < arr.length; i++) {
        for (var j = 0; j < arr[i][1].length; j++) {
            if (arr[i][1][j] == strRsn) {
                return arr[i][0];
            }
        }
    }
    return -1;
};
scwin.fn_dscl = async function() {
    var vRsnCd = dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "STK_ISU_RSN_CD");
    var vListDD = dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "LIST_DD");
    var vMethdTpCd = dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "LIST_METHD_TP_CD");

    //var vBzProcsNo = dts_IssList.NameString(dts_IssList.RowPosition, "BZ_PROCS_NO");
    var vBzProcsNo = "";
    for (var i = 1; i <= dts_IssList.getTotalRow(); i++) {
        vBzProcsNo = vBzProcsNo + (vBzProcsNo == "" ? "" : ",") + dts_IssList.getCellData(i, "BZ_PROCS_NO");
    }
    if (vRsnCd == "" || vBzProcsNo == "") {
        $c.win.alert("[대상]을 선택하세요.");
        return;
    }
    /*
    if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    	alert(getMessageParam("MSG-0022", ""));
    	return ;
    }
    alert("vRsnCd."+vRsnCd)
    alert("vListDD."+vListDD)
    alert("vBzProcsNo."+vBzProcsNo)
    */
    var rsnKey = scwin.fn_getRsnCse(vRsnCd);
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;

    // 우선주의보통주전환사유 변경상장,추가상장 둘다 존재(2017.05.18)
    if (vRsnCd == '625') {
        if (vMethdTpCd == '2') {
            // 추가상장
            rsnKey = '130';
        } else if (vMethdTpCd == '3') {
            // 변경상장
            rsnKey = '141';
        }
    }

    //alert("발행사유코드 -->"+rsnKey + " vRsnCd:" + vRsnCd);

    if (rsnKey == "148") {
        // 상호변경
        var url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_COM_NM_CHG_DSCL_KOSDAQ + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD;
        dts_DsclMst.DataID = encodeURI(url);
        dts_DsclMst.reset();

        /* 2009.05.22 영문공시 추가 */
        url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_COM_NM_CHG_DSCL_KOSDAQ_ENG + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD;
        dts_DsclMst_Eng.DataID = encodeURI(url);
        dts_DsclMst_Eng.reset();
        var dBzProcsNo = vBzProcsNo;
        for (var i = 1; i <= dts_DsclMst.getTotalRow(); i++) {
            dBzProcsNo = dBzProcsNo + (dBzProcsNo == "" ? "" : ",") + dts_DsclMst.getCellData(i, "BZ_PROCS_NO");
        }
        /*
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        	arr[0] = "70765";
        	arr[1] = vBzProcsNo;
        	arr[2] = vIsurCd;
        	//CopyDataSet( dts_Delistdetail , param_dts_isu) ;
        	CopyDataSet( dts_DsclMst, param_dts_mst) ;
        	CopyDataSet( dts_IssList, param_dts2) ;
        	return arr.length;
        }
        */
        //fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng) {
        scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
            if (js_market == "2") {
                arr[0] = "70765";
            } else {
                //코넥스
                arr[0] = "32005";
            }
            arr[1] = dBzProcsNo;
            arr[2] = scwin.vIsurCd;
            $c.stf.CopyDataSet(dts_DsclMst, param_dts_mst);
            $c.stf.CopyDataSet(dts_IssList, param_dts2);
            $c.stf.CopyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
            $c.stf.CopyDataSet(dts_IssList_Eng, param_dts_dtl_eng);
            return arr.length;
        };
    } else if (rsnKey == "141A") {
        // 액면변경
        var url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_MAIN_PAR_CHG_DSCL_KOSDAQ + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD;
        dts_DsclMst.DataID = encodeURI(url);
        dts_DsclMst.reset();
        url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_BODY_DSCL_KOSDAQ + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD + "&GUBUN_CD=" + vRsnCd + "&LIST_METHD_TP_CD=" + vMethdTpCd;
        dts_DsclDtl.DataID = encodeURI(url);
        dts_DsclDtl.reset();

        /* 2009.06.03 영문공시 추가 */
        url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_MAIN_PAR_CHG_DSCL_KOSDAQ_ENG + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD;
        dts_DsclMst_Eng.DataID = encodeURI(url);
        dts_DsclMst_Eng.reset();
        url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_BODY_DSCL_KOSDAQ_ENG + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD + "&GUBUN_CD=" + vRsnCd + "&LIST_METHD_TP_CD=" + vMethdTpCd;
        dts_DsclDtl_Eng.DataID = encodeURI(url);
        dts_DsclDtl_Eng.reset();


        /*
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        	arr[0] = "70764";
        	arr[1] = vBzProcsNo ;
        	arr[2] = vIsurCd ;
        	//CopyDataSet( dts_Delistdetail , param_dts_isu) ;
        	CopyDataSet( dts_DsclMst, param_dts_mst) ;
        	CopyDataSet( dts_DsclDtl, param_dts2) ;
        	return arr.length;
        }
        */
        //fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng, param_dts_dtl_eng) {
        scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
            if (js_market == "2") {
                arr[0] = "70764";
            } else {
                arr[0] = "32006";
            }
            arr[1] = vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            $c.stf.CopyDataSet(dts_DsclMst, param_dts_mst);
            $c.stf.CopyDataSet(dts_DsclDtl, param_dts2);
            $c.stf.CopyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
            $c.stf.CopyDataSet(dts_DsclDtl_Eng, param_dts_dtl_eng);
            return arr.length;
        };
    } else if (rsnKey == "141" || rsnKey == "130") {
        // 변경상장 141, 추가상장 130
        var url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_MAIN_DSCL_KOSDAQ + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD + "&GUBUN_CD=" + vRsnCd + "&LIST_METHD_TP_CD=" + vMethdTpCd;
        dts_DsclMst.DataID = encodeURI(url);
        dts_DsclMst.reset();
        url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_BODY_DSCL_KOSDAQ + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD + "&GUBUN_CD=" + vRsnCd + "&LIST_METHD_TP_CD=" + vMethdTpCd;
        dts_DsclDtl.DataID = encodeURI(url);
        dts_DsclDtl.reset();

        /* 2009.06.03 영문공시 추가 */
        url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_MAIN_DSCL_KOSDAQ_ENG + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD + "&GUBUN_CD=" + vRsnCd + "&LIST_METHD_TP_CD=" + vMethdTpCd;
        dts_DsclMst_Eng.DataID = encodeURI(url);
        dts_DsclMst_Eng.reset();
        url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_BODY_DSCL_KOSDAQ_ENG + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD + "&GUBUN_CD=" + vRsnCd + "&LIST_METHD_TP_CD=" + vMethdTpCd;
        dts_DsclDtl_Eng.DataID = encodeURI(url);
        dts_DsclDtl_Eng.reset();
        if (rsnKey == "141") {
            /*
            fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            	arr[0] = "70763";
            	arr[1] = vBzProcsNo ;
            	arr[2] = vIsurCd ;
            	//CopyDataSet( dts_Delistdetail , param_dts_isu) ;
            	CopyDataSet( dts_DsclMst, param_dts_mst) ;
            	CopyDataSet( dts_DsclDtl, param_dts2) ;
            	return arr.length;
            }
            */
            //fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng, param_dts_dtl_eng) {
            scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
                if (js_market == "2") {
                    arr[0] = "70763";
                } else {
                    arr[0] = "32004"; //코넥스 변경상장

                }
                arr[1] = vBzProcsNo;
                arr[2] = scwin.vIsurCd;
                $c.stf.CopyDataSet(dts_DsclMst, param_dts_mst);
                $c.stf.CopyDataSet(dts_DsclDtl, param_dts2);
                $c.stf.CopyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
                $c.stf.CopyDataSet(dts_DsclDtl_Eng, param_dts_dtl_eng);
                return arr.length;
            };
        } else if (rsnKey == "130") {
            /*
            fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            	arr[0] = "70791";
            	arr[1] = vBzProcsNo ;
            	arr[2] = vIsurCd ;
            	//CopyDataSet( dts_Delistdetail , param_dts_isu) ;
            	CopyDataSet( dts_DsclMst, param_dts_mst) ;
            	CopyDataSet( dts_DsclDtl, param_dts2) ;
            	return arr.length;
            }
            */
            //fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng, param_dts_dtl_eng) {
            scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
                if (js_market == "2") {
                    arr[0] = "70791";
                } else {
                    arr[0] = "32003"; //코넥스 추가상장

                }
                arr[1] = vBzProcsNo;
                arr[2] = scwin.vIsurCd;
                $c.stf.CopyDataSet(dts_DsclMst, param_dts_mst);
                $c.stf.CopyDataSet(dts_DsclDtl, param_dts2);
                $c.stf.CopyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
                $c.stf.CopyDataSet(dts_DsclDtl_Eng, param_dts_dtl_eng);
                return arr.length;
            };
        }
        /* 2009.05.22 영문공시 추가 끝 */
        /* 2009.07.01 영문공시 추가 - 추가상장(종목) : 국문,영문 */
    } else if (rsnKey == "100B") {
        // 추가상장
        //alert("추가상장(종목)");
        var url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_ABBRV_CHG_DSCL_KOSDAQ + "&ISUR_CD=" + scwin.vIsurCd + "&ISUR_CD=" + scwin.vIsurCd + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD + "&GUBUN_CD=" + vRsnCd;
        dts_DsclMst.DataID = encodeURI(url);
        dts_DsclMst.reset();

        //영문
        url = "/Listing.do?method=searchIsuIssDsclList" + "&DIV_IDX=" + DIV_IDX_STK_ISS_ABBRV_CHG_DSCL_KOSDAQ_ENG + "&ISUR_CD=" + scwin.vIsurCd + "&ISUR_CD=" + scwin.vIsurCd + "&ISUR_CD=" + scwin.vIsurCd + "&LIST_DD=" + vListDD + "&GUBUN_CD=" + vRsnCd;
        dts_DsclMst_Eng.DataID = encodeURI(url);
        dts_DsclMst_Eng.reset();
        scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
            if (js_market == "2") {
                arr[0] = "70762";
            } else {
                arr[0] = "32013"; //코넥스 추가상장(종목)

            }
            arr[1] = vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            $c.stf.CopyDataSet(dts_DsclMst, param_dts_mst);
            $c.stf.CopyDataSet(dts_DsclDtl, param_dts2);
            $c.stf.CopyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
            $c.stf.CopyDataSet(dts_DsclDtl_Eng, param_dts_dtl_eng);
            //alert(dts_DsclMst_Eng.Text);				
            return arr.length;
        };
    }

    //alert (dts_DsclMst.Text);
    //alert (dts_DsclDtl.Text);

    scwin.fn_SetPar = function(arr) {

    };
    var wth = 745 + 5;
    var hgt = 795 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    //frame.CreateDialogFrame("ULDSTF92024_EN", "/listingcommon/ULDSTF92024_EN.gfm", "영문공시안내문작성", pt.x, pt.y, wth, hgt, "window");

    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.btn_Dscl_onclick = function() {
    scwin.fn_dscl();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_IssRecv_OnClick = function(row, colid) {
    scwin.fn_OpenDetail(row);
};
scwin.dts_IssRecv_OnLoadError = function() {
    $c.stf.alert_error(dts_IssRecv);
};
scwin.dts_IssList_OnLoadError = function() {
    $c.stf.alert_error(dts_IssList);
};
scwin.dts_DsclMst_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclMst);
};
scwin.dts_DsclDtl_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclDtl);
};
scwin.dts_IssList_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(edt_IssListTotalCnt, "총 " + rowcount + " 건");
    $c.cm.CloseWin(rowcount, grd_IssList);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    var parentWin = $c.frame.path("../");
    scwin.vIsurCd = $c.stf.getObjectValue(parentWin.txb_ISUR_CD);
    scwin.fn_list_sync();
};
